/** urn:corpus:claims:claim:operation:approve_claim — ensures: output.version = input.version + 1 */
export const ClaimApproveClaimEnsures1 = (p: { input: ClaimChange; current: ClaimClaim; output: ClaimAnswer }): boolean =>
  (p.output.version as number) === ((p.input.version as number) + 1);

/** urn:corpus:claims:claim:operation:approve_claim — ensures: output.total = current.total */
export const ClaimApproveClaimEnsures2 = (p: { input: ClaimChange; current: ClaimClaim; output: ClaimAnswer }): boolean =>
  compareDecimal((p.output.total as string), (p.current.total as string)) === 0;

/** urn:corpus:claims:claim:operation:approve_claim — ensures: output.currency = current.currency */
export const ClaimApproveClaimEnsures3 = (p: { input: ClaimChange; current: ClaimClaim; output: ClaimAnswer }): boolean =>
  (p.output.currency as string) === (p.current.currency as string);

/** urn:corpus:claims:claim:operation:create_draft — ensures: output.currency = input.currency */
export const ClaimCreateDraftEnsures1 = (p: { input: ClaimDraft; output: ClaimAnswer }): boolean =>
  (p.output.currency as string) === (p.input.currency as string);

/** urn:corpus:claims:claim:operation:create_draft — ensures: output.total = sum(line in input.lines: line.amount) */
export const ClaimCreateDraftEnsures2 = (p: { input: ClaimDraft; output: ClaimAnswer }): boolean =>
  compareDecimal((p.output.total as string), ((p.input.lines ?? []) as readonly any[]).reduce((total: string, line) => addDecimal(total, (line.amount as string)), '0')) === 0;

